mapper.select:
SELECT id, document_code, user_id, user_name, borrow_time, return_time, status
FROM borrowing_records
WHERE document_code = #{documentCode}
  AND user_id = #{userId}
  AND user_name = #{userName}
  AND status = '借阅中'
ORDER BY borrow_time DESC
LIMIT 1

mapper.update:
UPDATE borrowing_records
SET return_time = #{returnTime},
    status = #{status}
WHERE id = #{id}
